use kimo_core::{effects::{Frame,Params,apply},model::Effect,color::wrapper::configure};
#[test]fn identity_encoding_sandwich(){let mut e=Effect{id:"e".into(),kind:"saturation".into(),params:Params::new(),strings:Default::default()};configure(&mut e,3,0,1).unwrap();let c=[0.1,0.2,0.3,0.6];let mut f=Frame{w:1,h:1,d:c.to_vec()};apply(&e.kind,&e.params,&e.strings,&mut f,0.,0).unwrap();for j in 0..4{assert!((f.d[j]-c[j]).abs()<2e-7)}}
#[test]fn pq_wrapper_uses_declared_white(){use kimo_core::{keyframe::Prop,color::{wrapper::configure_white,managed}};let mut e=Effect{id:"e".into(),kind:"color_wheels".into(),params:Params::new(),strings:Default::default()};e.params.insert("lift_r".into(),Prop::new(0.));configure_white(&mut e,1,1,6,203.).unwrap();let c=[0.1,0.2,0.3,1.];let mut f=Frame{w:1,h:1,d:c.to_vec()};apply(&e.kind,&e.params,&e.strings,&mut f,0.,0).unwrap();for j in 0..3{assert!((f.d[j]-c[j]).abs()<2e-6)}assert_eq!(e.strings["wrapper_reference_white"],"203");let mut direct=Frame{w:1,h:1,d:c.to_vec()};let mut pr=Params::new();for(k,v)in[("from_gamut",1.),("to_gamut",1.),("from_transfer",0.),("to_transfer",6.),("reference_white",203.)]{pr.insert(k.into(),Prop::new(v));}managed::apply(&pr,&mut direct,0.).unwrap();assert!((direct.d[0] as f64-managed::encode(6,0.1,203.)).abs()<1e-6);}
#[test]fn pq_wrapper_effect_matches_explicit_chain(){use kimo_core::{color::{wrapper::configure_white,managed},keyframe::Prop};let mut e=Effect{id:"e".into(),kind:"exposure".into(),params:Params::new(),strings:Default::default()};e.params.insert("stops".into(),Prop::new(-0.25));configure_white(&mut e,1,1,6,203.).unwrap();let mut f=Frame{w:1,h:1,d:vec![0.1,0.2,0.3,1.]};let mut reference=Frame{w:1,h:1,d:f.d.clone()};let mut pr=Params::new();for(k,v)in[("from_gamut",1.),("to_gamut",1.),("from_transfer",0.),("to_transfer",6.),("reference_white",203.)]{pr.insert(k.into(),Prop::new(v));}managed::apply(&pr,&mut reference,0.).unwrap();apply("exposure",&e.params,&Default::default(),&mut reference,0.,0).unwrap();pr.insert("from_transfer".into(),Prop::new(6.));pr.insert("to_transfer".into(),Prop::new(0.));managed::apply(&pr,&mut reference,0.).unwrap();apply(&e.kind,&e.params,&e.strings,&mut f,0.,0).unwrap();assert_eq!(f.d,reference.d);}
